async (page) => {
  const events = [];
  page.on('pageerror', e => events.push({t:'pageerror', m: e.message}));
  page.on('console', m => { if (m.type()==='error' || m.type()==='warning') events.push({t:'console-'+m.type(), m: m.text()}); });
  const cdp = await page.context().newCDPSession(page);
  await cdp.send('Runtime.enable');
  cdp.on('Runtime.exceptionThrown', p => events.push({t:'cdp', m: p.exceptionDetails.text + ' | ' + (p.exceptionDetails.exception?.description||'')}));
  const buttons = await page.locator('button').all();
  const out = [];
  for (const b of buttons) {
    const label = await b.innerText();
    const sec = await b.evaluate(el => (el.closest('section,div,li')||el).innerText.slice(0,80));
    events.length = 0;
    await b.click();
    await page.waitForTimeout(1500);
    out.push({label, sec, events: [...events]});
  }
  return out;
}

